mkuse!{use rustc_ast :: util :: classify ;}
mkuse!{use rustc_ast :: util :: parser :: { self , ExprPrecedence } ;}
mkuse!{use rustc_ast :: { Expr , ExprKind , YieldKind } ;}
mkitem!{mkstruct!{# [derive (Copy , Clone , Debug , Default)] pub (crate) struct FixupContext { # [doc = " Print expression such that it can be parsed back as a statement"] # [doc = " consisting of the original expression."] # [doc = ""] # [doc = " The effect of this is for binary operators in statement position to set"] # [doc = " `leftmost_subexpression_in_stmt` when printing their left-hand operand."] # [doc = ""] # [doc = " ```ignore (illustrative)"] # [doc = " (match x {}) - 1;  // match needs parens when LHS of binary operator"] # [doc = ""] # [doc = " match x {};  // not when its own statement"] # [doc = " ```"] stmt : bool , # [doc = " This is the difference between:"] # [doc = ""] # [doc = " ```ignore (illustrative)"] # [doc = " (match x {}) - 1;  // subexpression needs parens"] # [doc = ""] # [doc = " let _ = match x {} - 1;  // no parens"] # [doc = " ```"] # [doc = ""] # [doc = " There are 3 distinguishable contexts in which `print_expr` might be"] # [doc = " called with the expression `$match` as its argument, where `$match`"] # [doc = " represents an expression of kind `ExprKind::Match`:"] # [doc = ""] # [doc = "   - stmt=false leftmost_subexpression_in_stmt=false"] # [doc = ""] # [doc = "     Example: `let _ = $match - 1;`"] # [doc = ""] # [doc = "     No parentheses required."] # [doc = ""] # [doc = "   - stmt=false leftmost_subexpression_in_stmt=true"] # [doc = ""] # [doc = "     Example: `$match - 1;`"] # [doc = ""] # [doc = "     Must parenthesize `($match)`, otherwise parsing back the output as a"] # [doc = "     statement would terminate the statement after the closing brace of"] # [doc = "     the match, parsing `-1;` as a separate statement."] # [doc = ""] # [doc = "   - stmt=true leftmost_subexpression_in_stmt=false"] # [doc = ""] # [doc = "     Example: `$match;`"] # [doc = ""] # [doc = "     No parentheses required."] leftmost_subexpression_in_stmt : bool , # [doc = " Print expression such that it can be parsed as a match arm."] # [doc = ""] # [doc = " This is almost equivalent to `stmt`, but the grammar diverges a tiny bit"] # [doc = " between statements and match arms when it comes to braced macro calls."] # [doc = " Macro calls with brace delimiter terminate a statement without a"] # [doc = " semicolon, but do not terminate a match-arm without comma."] # [doc = ""] # [doc = " ```ignore (illustrative)"] # [doc = " m! {} - 1;  // two statements: a macro call followed by -1 literal"] # [doc = ""] # [doc = " match () {"] # [doc = "     _ => m! {} - 1,  // binary subtraction operator"] # [doc = " }"] # [doc = " ```"] match_arm : bool , # [doc = " This is almost equivalent to `leftmost_subexpression_in_stmt`, other"] # [doc = " than for braced macro calls."] # [doc = ""] # [doc = " If we have `m! {} - 1` as an expression, the leftmost subexpression"] # [doc = " `m! {}` will need to be parenthesized in the statement case but not the"] # [doc = " match-arm case."] # [doc = ""] # [doc = " ```ignore (illustrative)"] # [doc = " (m! {}) - 1;  // subexpression needs parens"] # [doc = ""] # [doc = " match () {"] # [doc = "     _ => m! {} - 1,  // no parens"] # [doc = " }"] # [doc = " ```"] leftmost_subexpression_in_match_arm : bool , # [doc = " This is the difference between:"] # [doc = ""] # [doc = " ```ignore (illustrative)"] # [doc = " if let _ = (Struct {}) {}  // needs parens"] # [doc = ""] # [doc = " match () {"] # [doc = "     () if let _ = Struct {} => {}  // no parens"] # [doc = " }"] # [doc = " ```"] parenthesize_exterior_struct_lit : bool , # [doc = " This is the difference between:"] # [doc = ""] # [doc = " ```ignore (illustrative)"] # [doc = " let _ = (return) - 1;  // without paren, this would return -1"] # [doc = ""] # [doc = " let _ = return + 1;  // no paren because '+' cannot begin expr"] # [doc = " ```"] next_operator_can_begin_expr : bool , # [doc = " This is the difference between:"] # [doc = ""] # [doc = " ```ignore (illustrative)"] # [doc = " let _ = 1 + return 1;  // no parens if rightmost subexpression"] # [doc = ""] # [doc = " let _ = 1 + (return 1) + 1;  // needs parens"] # [doc = " ```"] next_operator_can_continue_expr : bool , }}}
mkitem!{mkimpl!{impl FixupContext { # [doc = " Create the initial fixup for printing an expression in statement"] # [doc = " position."] pub (crate) fn new_stmt () -> Self { FixupContext { stmt : true , .. FixupContext :: default () } } # [doc = " Create the initial fixup for printing an expression as the right-hand"] # [doc = " side of a match arm."] pub (crate) fn new_match_arm () -> Self { FixupContext { match_arm : true , .. FixupContext :: default () } } # [doc = " Create the initial fixup for printing an expression as the \"condition\""] # [doc = " of an `if` or `while`. There are a few other positions which are"] # [doc = " grammatically equivalent and also use this, such as the iterator"] # [doc = " expression in `for` and the scrutinee in `match`."] pub (crate) fn new_cond () -> Self { FixupContext { parenthesize_exterior_struct_lit : true , .. FixupContext :: default () } } # [doc = " Transform this fixup into the one that should apply when printing the"] # [doc = " leftmost subexpression of the current expression."] # [doc = ""] # [doc = " The leftmost subexpression is any subexpression that has the same first"] # [doc = " token as the current expression, but has a different last token."] # [doc = ""] # [doc = " For example in `$a + $b` and `$a.method()`, the subexpression `$a` is a"] # [doc = " leftmost subexpression."] # [doc = ""] # [doc = " Not every expression has a leftmost subexpression. For example neither"] # [doc = " `-$a` nor `[$a]` have one."] pub (crate) fn leftmost_subexpression (self) -> Self { FixupContext { stmt : false , leftmost_subexpression_in_stmt : self . stmt || self . leftmost_subexpression_in_stmt , match_arm : false , leftmost_subexpression_in_match_arm : self . match_arm || self . leftmost_subexpression_in_match_arm , next_operator_can_begin_expr : false , next_operator_can_continue_expr : true , .. self } } # [doc = " Transform this fixup into the one that should apply when printing a"] # [doc = " leftmost subexpression followed by a `.` or `?` token, which confer"] # [doc = " different statement boundary rules compared to other leftmost"] # [doc = " subexpressions."] pub (crate) fn leftmost_subexpression_with_dot (self) -> Self { FixupContext { stmt : self . stmt || self . leftmost_subexpression_in_stmt , leftmost_subexpression_in_stmt : false , match_arm : self . match_arm || self . leftmost_subexpression_in_match_arm , leftmost_subexpression_in_match_arm : false , next_operator_can_begin_expr : false , next_operator_can_continue_expr : true , .. self } } # [doc = " Transform this fixup into the one that should apply when printing a"] # [doc = " leftmost subexpression followed by punctuation that is legal as the"] # [doc = " first token of an expression."] pub (crate) fn leftmost_subexpression_with_operator (self , next_operator_can_begin_expr : bool ,) -> Self { FixupContext { next_operator_can_begin_expr , .. self . leftmost_subexpression () } } # [doc = " Transform this fixup into the one that should apply when printing the"] # [doc = " rightmost subexpression of the current expression."] # [doc = ""] # [doc = " The rightmost subexpression is any subexpression that has a different"] # [doc = " first token than the current expression, but has the same last token."] # [doc = ""] # [doc = " For example in `$a + $b` and `-$b`, the subexpression `$b` is a"] # [doc = " rightmost subexpression."] # [doc = ""] # [doc = " Not every expression has a rightmost subexpression. For example neither"] # [doc = " `[$b]` nor `$a.f($b)` have one."] pub (crate) fn rightmost_subexpression (self) -> Self { FixupContext { stmt : false , leftmost_subexpression_in_stmt : false , match_arm : false , leftmost_subexpression_in_match_arm : false , .. self } } # [doc = " Determine whether parentheses are needed around the given expression to"] # [doc = " head off an unintended statement boundary."] # [doc = ""] # [doc = " The documentation on `FixupContext::leftmost_subexpression_in_stmt` has"] # [doc = " examples."] pub (crate) fn would_cause_statement_boundary (self , expr : & Expr) -> bool { (self . leftmost_subexpression_in_stmt && ! classify :: expr_requires_semi_to_be_stmt (expr)) || (self . leftmost_subexpression_in_match_arm && classify :: expr_is_complete (expr)) } # [doc = " Determine whether parentheses are needed around the given `let`"] # [doc = " scrutinee."] # [doc = ""] # [doc = " In `if let _ = $e {}`, some examples of `$e` that would need parentheses"] # [doc = " are:"] # [doc = ""] # [doc = "   - `Struct {}.f()`, because otherwise the `{` would be misinterpreted"] # [doc = "     as the opening of the if's then-block."] # [doc = ""] # [doc = "   - `true && false`, because otherwise this would be misinterpreted as a"] # [doc = "     \"let chain\"."] pub (crate) fn needs_par_as_let_scrutinee (self , expr : & Expr) -> bool { self . parenthesize_exterior_struct_lit && parser :: contains_exterior_struct_lit (expr) || parser :: needs_par_as_let_scrutinee (self . precedence (expr)) } # [doc = " Determines the effective precedence of a subexpression. Some expressions"] # [doc = " have higher or lower precedence when adjacent to particular operators."] pub (crate) fn precedence (self , expr : & Expr) -> ExprPrecedence { if self . next_operator_can_begin_expr { if let ExprKind :: Break (..) | ExprKind :: Ret (..) | ExprKind :: Yeet (..) | ExprKind :: Yield (YieldKind :: Prefix (..)) = expr . kind { return ExprPrecedence :: Jump ; } } if ! self . next_operator_can_continue_expr { if let ExprKind :: Break (..) | ExprKind :: Closure (..) | ExprKind :: Ret (..) | ExprKind :: Yeet (..) | ExprKind :: Yield (YieldKind :: Prefix (..)) | ExprKind :: Range (None , ..) = expr . kind { return ExprPrecedence :: Prefix ; } } expr . precedence () } }}}